@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea class="form-control mb-3" rows="12" @bind="Content" @bind:event="oninput"
          @bind:after="OnContentChanged"></textarea>

<div class="d-flex align-items-center gap-2 mb-3">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>

    @if (_lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @_lastSavedAt</span>
    }
</div>

@code {
    private string Content { get; set; } = string.Empty;

    private string? _lastSavedAt;
    private bool _isDirty;
    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;
    private System.Threading.Timer? _autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            _dotNetRef = DotNetObjectReference.Create(this);

            var saved = await _interop.InitializeAsync(_dotNetRef);
            if (!string.IsNullOrEmpty(saved))
            {
                Content = saved;
                StateHasChanged();
            }

            _autoSaveTimer = new System.Threading.Timer(
                async _ => await AutoSaveCallback(),
                null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));
        }
    }

    private async Task OnContentChanged()
    {
        if (!_isDirty)
        {
            _isDirty = true;
            await MarkDirtyInJs();
        }
    }

    private async Task MarkDirtyInJs()
    {
        if (_interop is not null)
        {
            var module = await JS.InvokeAsync<IJSObjectReference>("import", NotepadInterop.ModulePath);
            await module.InvokeVoidAsync("markDirty");
            await module.DisposeAsync();
        }
    }

    private async Task AutoSaveCallback()
    {
        if (_isDirty && _interop is not null)
        {
            await InvokeAsync(async () =>
            {
                _lastSavedAt = await _interop.SaveAsync(Content);
                _isDirty = false;
                StateHasChanged();
            });
        }
    }

    private async Task SaveNowAsync()
    {
        if (_interop is not null)
        {
            _lastSavedAt = await _interop.SaveAsync(Content);
            _isDirty = false;
        }
    }

    private async Task ClearAsync()
    {
        if (_interop is not null)
        {
            Content = string.Empty;
            _lastSavedAt = null;
            _isDirty = false;
            await _interop.ClearAsync();
        }
    }

    [JSInvokable]
    public async Task OnDirtyChanged(bool dirty)
    {
        await InvokeAsync(() =>
        {
            _isDirty = dirty;
            StateHasChanged();
        });
    }

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
            await _autoSaveTimer.DisposeAsync();

        try
        {
            if (_interop is not null)
                await _interop.DisposeAsync();
        }
        catch (JSDisconnectedException) { }

        _dotNetRef?.Dispose();
    }
}

using Microsoft.JSInterop;

namespace sv_9704640198894e02bbd4f69f3344c79d.Components.Pages;

public sealed class NotepadInterop : IAsyncDisposable
{
    internal const string ModulePath = "./Components/Pages/Notepad.razor.js";
    internal const string InitMethod = "initialize";
    internal const string SaveMethod = "save";
    internal const string ClearMethod = "clear";
    internal const string DisposeMethod = "dispose";

    private readonly IJSRuntime _js;
    private IJSObjectReference? _module;

    public NotepadInterop(IJSRuntime js) => _js = js;

    private async ValueTask<IJSObjectReference> GetModuleAsync()
        => _module ??= await _js.InvokeAsync<IJSObjectReference>("import", ModulePath);

    /// <summary>
    /// Loads saved content from localStorage and registers the beforeunload listener.
    /// Returns the previously saved content, or null if none exists.
    /// </summary>
    public async ValueTask<string?> InitializeAsync(DotNetObjectReference<Notepad> dotNetRef)
    {
        var module = await GetModuleAsync();
        return await module.InvokeAsync<string?>(InitMethod, dotNetRef);
    }

    /// <summary>
    /// Saves content to localStorage and returns the formatted time string (HH:MM:SS).
    /// </summary>
    public async ValueTask<string> SaveAsync(string content)
    {
        var module = await GetModuleAsync();
        return await module.InvokeAsync<string>(SaveMethod, content);
    }

    /// <summary>
    /// Clears content from localStorage and removes the dirty flag.
    /// </summary>
    public async ValueTask ClearAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(ClearMethod);
    }

    public async ValueTask DisposeAsync()
    {
        try
        {
            if (_module is not null)
            {
                await _module.InvokeVoidAsync(DisposeMethod);
                await _module.DisposeAsync();
            }
        }
        catch (JSDisconnectedException) { }
    }
}

const STORAGE_KEY = 'notepad-content';
const ON_DIRTY_CHANGED = 'OnDirtyChanged';

let dotNetRef;
let abortController;

function beforeUnloadHandler(e) {
    e.preventDefault();
}

export function initialize(ref) {
    dotNetRef = ref;
    abortController = new AbortController();

    const saved = localStorage.getItem(STORAGE_KEY);
    return saved;
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);

    // Mark clean — remove beforeunload listener
    abortController.abort();
    abortController = new AbortController();

    try {
        dotNetRef.invokeMethodAsync(ON_DIRTY_CHANGED, false);
    } catch { /* circuit disconnected */ }

    const now = new Date();
    const hh = String(now.getHours()).padStart(2, '0');
    const mm = String(now.getMinutes()).padStart(2, '0');
    const ss = String(now.getSeconds()).padStart(2, '0');
    return `${hh}:${mm}:${ss}`;
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);

    // Mark clean
    abortController.abort();
    abortController = new AbortController();

    try {
        dotNetRef.invokeMethodAsync(ON_DIRTY_CHANGED, false);
    } catch { /* circuit disconnected */ }
}

export function markDirty() {
    window.addEventListener('beforeunload', beforeUnloadHandler, {
        signal: abortController.signal
    });
}

export function dispose() {
    abortController?.abort();
}

